#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long n;
    std::cin >> n;

    const long long MOD = 1000000007;

    // a = F(i), b = F(i+1). After n steps, a is F(n).
    long long a = 0;
    long long b = 1;
    for (long long i = 0; i < n; ++i) {
        long long next = (a + b) % MOD;
        a = b;
        b = next;
    }

    std::cout << a << '\n';
}
